// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        assert(address(c).balance == amount);

        address recipient = address(0xBEEF);
        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);
    }
}
